  List<int> freq = [];
  for (int code in barcodes) {
    if (uniqueCodes.isEmpty || uniqueCodes.last != code) {
      uniqueCodes.add(code);
      freq.add(1);
    } else {
      int idx = uniqueCodes.indexOf(code);
      freq[idx]++;
    }
  }
  int k = freq.length;
  List<int> result = [];
  List<int> freqs = List.generate(k, (i) => freq[i]);
  freqs.sort((a, b) => b.compareTo(a));
  for (int i = 0; i < k; i++) {
    int count = freqs[i];
    for (int j = 0; j < count; j++) {
      result.add(uniqueCodes[i]);
    }
  }
  return result;
}

