List<String> allSegmentations(String s, List<String> wordBreak) {
  if (s.isEmpty) return [];
  Set<String> wordDict = wordBreak.toSet();
  List<String> segmentations = [];

  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordDict.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (!dp[s.length]) return [];

  List<int> ends = [];
  for (int i = 0; i <= s.length; i++) {
    if (dp[i]) ends.add(i);
  }

  for (int i = 0; i < ends.length; i++) {
    List<int> startIndices = [];
    for (int j = 0; j < ends.length; j++) {
      if (i != j) startIndices.add(ends[j]);
    }

    List<String> seg = [];
    int currEnd = ends[i];
    for (int st in startIndices) {
      while (currEnd < currEnd) {
        seg.add(s.substring(st, currEnd));
        currEnd++;
      }
    }

    segmentations.add(seg.join(' '));
  }

  return segmentations;
}

int minWordsNeeded(String s, List<String> wordBreak) {
  if (s.isEmpty) return 0;
  Set<String> wordDict = wordBreak.toSet();
  List<int> dp = List.filled(s.length + 1, 1000000000);
  dp[0] = 0; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordDict.contains(s.substring(j, i)) && dp[j] != 1000000000) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[s.length];
}

