Map<String, int> fn0(List<String> commands) {
  Map<String, int> result = {
    'BEGIN': 0,
    'END': 0,
    'ADD': 0,
    'UNDO': 0
  };
  List<List<int>> logs = [
    [0, 0],
    [0, 0]
  ];
  List<String> stack = [];
  for (String cmd in commands) {
    if (cmd == 'BEGIN') {
      logs.add([0, 0]);
      stack.add('BEGIN');
    } else if (cmd == 'END') {
      String top = stack.removeLast();
      if (top == 'BEGIN') {
        result['BEGIN'] = result['BEGIN']! + 1;
      } else if (top == 'ADD') {
        result['ADD'] = result['ADD']! + 1;
      } else if (top == 'UNDO') {
        result['UNDO'] = result['UNDO']! + 1;
      }
      logs.removeLast();
    } else if (cmd == 'ADD') {
      int prev = logs.last[0];
      int curr = logs.last[1];
      logs.add([prev + 1, curr]);
      stack.add('ADD');
    } else if (cmd == 'UNDO') {
      if (stack.isNotEmpty && stack.last == 'ADD') {
        String top = stack.removeLast();
        int idx = logs.length - 1;
        while (idx > 0) {
          if (logs[idx][0] > 1) {
            logs[idx][0] = logs[idx][0] - 1;
            break;
          }
          idx--;
        }
        stack.add(top);
        result['UNDO'] = result['UNDO']! + 1;
      }
    }
  }
  List<List<int>> sorted = [...logs];
  sorted.sort((a, b) {
    int durA = a[0];
    int durB = b[0];
    if (durB != durA) return durB - durA;
    int countA = a[1];
    int countB = b[1];
    if (countB != countA) return countB - countA;
    return a[0] - b[0];
  });
  List<String> parts = [];
  for (var log in sorted) {
    int dur = log[0];
    int count = log[1];
    parts.add('${dur}*${count}');
  }
  return result;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

Map<String, int> fn0(List<String> commands) {
  List<List<int>> stack = [];
  List<List<String>> history = [];
  int total = 0;
  List<String> items = [];

  void undo() {
    if (stack.isNotEmpty) {
      var last = stack.removeLast();
      items.removeLast();
      history.add(['BEGIN', last[0], last[1]]);
    }
  }

  void begin(int id, String name) {
    if (name.isEmpty) {
      undo();
      return;
    }
    history.add(['BEGIN', id, name]);
    stack.add([id, name]);
    items.add(name);
  }

  void end(int id) {
    if (stack.isEmpty) {
      undo();
      return;
    }
    int last = stack.removeLast();
    items.removeLast();
    history.add(['END', id, last[1]]);
    total += last[0];
  }

  void add(int id, int quantity) {
    if (stack.isEmpty) {
      undo();
      return;
    }
    int last = stack.removeLast();
    items.removeLast();
    history.add(['ADD', id, last[1], quantity]);
    stack.add([id, last[1] + '*' + quantity.toString()]);
    total += last[0] * quantity;
  }

  for (var cmd in commands) {
    if (cmd == 'UNDO') {
      undo();
    } else if (cmd.startsWith('BEGIN')) {
      var parts = cmd.split(' ');
      int id = int.parse(parts[1]);
      String name = parts[2];
      begin(id, name);
    } else if (cmd.startsWith('END')) {
      var parts = cmd.split(' ');
      int id = int.parse(parts[1]);
      end(id);
    } else if (cmd.startsWith('ADD')) {
      var parts = cmd.split(' ');
      int id = int.parse(parts[1]);
      int qty = int.parse(parts[2]);
      add(id, qty);
    }
  }

  history = history.reversed.toList();
  return {'total': total, 'history': history, 'items': items};
}

