  ];

  List<String> lower = List.generate(
    testCases.length,
    (i) => testCases[i].toLowerCase(),
  );

  bool recursive(String s, String p, int lo, int hi) {
    if (hi < lo) return false;
    if (hi == lo) return s == p;

    int mid = (lo + hi) ~/ 2;
    String s1 = lower[mid];
    String p1 = lower[p.length - 1];

    if (s1 != p1) {
      return recursive(s, p, lo, mid - 1) || 
          recursive(s, p, mid + 1, hi);
    }

    List<String> candidates = [];
    int count = 0;
    for (int i = mid - 1; i >= lo; i--) {
      if (lower[i] == s1) {
        candidates.add(s[i]);
        count++;
      }
    }
    for (int i = mid + 1; i <= hi; i++) {
      if (lower[i] == s1) {
        candidates.add(s[i]);
        count++;
      }
    }

    if (count > 1) {
      String result = count == 1 ? s1 : '[$count]';
      return true;
    }

    return recursive(s, p, lo, mid - 1) || 
        recursive(s, p, mid + 1, hi);
  }

  for (String test in testCases) {
    String lowerTest = test.toLowerCase();

    List<String> lowerSub = List.generate(
      lowerTest.length,
      (i) => lowerTest[i],
    );

    List<int> dp = List.filled(
      lowerTest.length + 1,
      0,
    );

    for (int i = 0; i <= lowerTest.length; i++) {
      dp[i] = i;
    }

    for (int i = lowerTest.length - 1; i >= 0; i--) {
      for (int j = lowerTest.length; j >= 2; j--) {
        if (lowerSub[i] == lowerSub[j - 1]) {
          if (dp[j - 1] != 0) {
            dp[j] = dp[j] == 0 ? j : dp[j] + 1;
          }
        }
      }
    }

    bool found = recursive(test, lowerTest, 0, lowerTest.length);

    print('Pattern ${test.length} found at positions: ${found ? dp : "not found."}');
  }
}

