  if (sortedDurations.isEmpty || targetMinutes < 0) {
    return 0;
  }
  final int n = sortedDurations.length;
  final List<int> prefixSums = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefixSums[i + 1] = prefixSums[i] + sortedDurations[i] + i * 2;
  }
