    return 0;
  }

  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (int r = 0; r < rows; r++) {
    dp[r][0] = grid[r][0];
  }

  for (int c = 1; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      int maxSum = dp[r][c - 1];
      for (int j = 0; j < c; j++) {
        if (dp[r][j] > maxSum) {
          maxSum = dp[r][j];
        }
      }
      dp[r][c] = grid[r][c] + maxSum;
    }
  }

  int maxLen = 0;
  for (int r = 0; r < rows; r++) {
    if (dp[r][cols - 1] > maxLen) {
      maxLen = dp[r][cols - 1];
    }
  }

  return maxLen;
}

