  dp[0] = weights[0];
  for (int i = 1; i < n; i++) {
    dp[i] = dp[i - 1] + weights[i] - weights[i - 1];
  }
  if (capacity < 0) return 0.0;
  double best = 0.0;
  for (int i = 0; i < n; i++) {
    if (dp[i] <= capacity) {
      if (dp[i] > best) best = dp[i];
    }
  }
  return best;
}

