bool hasPath(Map<int, List<int>> graph, int u, int v) {
  if (!graph.containsKey(u) || !graph.containsKey(v)) return false;
  Set<int> visited = {};
  List<int> queue = [u];
  visited.add(u);
  while (queue.isNotEmpty) {
    int current = queue.removeAt(0);
    if (current == v) return true;
    for (int neighbor in graph[current]!) {
      if (!visited.contains(neighbor)) {
        queue.add(neighbor);
        visited.add(neighbor);
      }
    }
  }
  return false;
}

void dfs(Map<int, List<int>> graph, int node) {
  print('Node $node:');
  Set<int> visited = {};
  void recurse(int u) {
    if (visited.contains(u)) return;
    visited.add(u);
    print('  -> $u');
    for (int neighbor in graph[u]!) {
      recurse(neighbor);
    }
  }
  recurse(node);
}

