    for (int i = 1; i < symbol.length; i++) {
      if (symbol[i] == current[0]) {
        count++;
      } else {
        if (current.length > 1) {
          isSafe = false;
          break;
        }
        if (count >= 2 && !used.contains('$current$count')) {
          used.add('$current$count');
          valid.add('$current$count');
        }
