        count = 1;
      }
    }

    if (current.length > 1) {
      isSafe = false;
    } else if (count >= 2 && !used.contains('$current$count')) {
      used.add('$current$count');
      valid.add('$current$count');
    }

    if (isSafe) {
      runs.add(current);
    }
  }

  List<String> sorted = [];
  for (var run in runs) {
    List<int> counts = [];
    for (var symbol in symbols) {
      if (symbol.isEmpty) continue;
      if (symbol.length != run.length) continue;
      if (symbol[0] != run[0]) continue;
