    if (v * words.length > result.length) {
      result.add(v);
    }
  }

  List<int> sorted = List.generate(words.length, (i) => i);
  sorted.sort((a, b) => freq[a].compareTo(freq[b]));

  for (int i = 0; i < words.length && result.length < k; i++) {
    if (freq[i] * words.length >= k) {
