    return;
  }

  const int cols = n;
  const int rows = n;
  const int queens = n;

  final List<List<int>> board = List.generate(rows, (_) => List.filled(cols, 0));

  bool isSafe(int row, int col) {
    for (int r = 0; r < row; r++) {
