    }
    for (int r = row - 1, c = col - 1; r >= 0 && c >= 0; r--, c--) {
      if (board[r][c] == 1) return false;
    }
    for (int r = row - 1, c = col + 1; r >= 0 && c < cols; r--, c++) {
      if (board[r][c] == 1) return false;
    }
    return true;
  }

  void place(int row) {
    if (row == queens) {
      printSolution();
      return;
    }

    for (int col = 0; col < cols; col++) {
      if (isSafe(row, col)) {
        board[row][col] = 1;
        place(row + 1);
        board[row][col] = 0;
      }
    }
  }

  print('Solving N-Queens for N=$n');
  place(0);

  print('Total solutions: ${n * (1 << queens)}');
}

