  Quaternion.fromList(List<double> parts)
      : this(parts[0], parts[1], parts[2], parts[3]);

  Quaternion.identity() : this(1.0, 0.0, 0.0, 0.0);

  Quaternion.fromQuaternion(Quaternion q) : this(q.x, q.y, q.z, q.w);

  Quaternion.fromAxisAngle(List<double> axis, double angle) {
    double x = axis[0], y = axis[1], z = axis[2];
    double sin = sin(angle / 2.0);
    double cos = cos(angle / 2.0);
    return Quaternion(2.0 * sin * cos, sin * x * cos + cos * y * z,
        cos * x * cos + sin * y * z, sin * sin * x + cos * cos * z);
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  void normalize() {
    double n = norm();
    if (n != 0.0) {
      x = x / n;
      y = y / n;
      z = z / n;
      w = w / n;
    } else {
      x = 0.0;
      y = 0.0;
      z = 0.0;
      w = 1.0;
    }
  }

  void conjugate() {
    x = x.abs();
    y = y.abs();
    z = z.abs();
    w = w.abs();
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    double xx = x * x, yy = y * y, zz = z * z;
    double xy = x * y, xz = x * z, yz = y * z;
    return Quaternion(
        xx * other.w + xy * other.z + xz * other.y + yy * other.w,
        xy * other.w + yy * other.z + yz * other.x + zz * other.w,
        xz * other.w + yz * other.z + zz * other.x + xx * other.w);
  }

  Quaternion inverse() {
    double invW = 1.0 / w;
    return Quaternion(x * invW, y * invW, z * invW, w * invW);
  }

  void rotateAroundAxis(List<double> axis, double angle) {
    double sin = sin(angle / 2.0);
    double cos = cos(angle / 2.0);
    Quaternion q = Quaternion.fromAxisAngle(axis, angle);
    x = x * cos - y * sin + z * q.x + w * q.y;
    y = y * cos + x * sin + w * q.x - z * q.y;
    z = z * cos - w * sin + q.x * q.z + q.y * q.w;
    w = w * cos + sin * q.x + cos * q.y + q.z * q.w;
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

