      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator * (double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator * (Quaternion other) =>
      Quaternion(x * other.w - y * other.z - z * other.y,
          y * other.x + x * other.y - z * other.w,
          z * other.x + w * other.y - x * other.z,
          w * other.x - x * other.y - y * other.z);

  Quaternion conjugate() => Quaternion(x, y, -z, w);

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  void normalize() {
    double norm = norm();
    if (norm == 0) throw ArgumentError('Cannot normalize zero quaternion');
    x = x / norm;
    y = y / norm;
    z = z / norm;
    w = w / norm;
  }

  void invert() {
    if (w == 0) throw ArgumentError('Cannot invert zero quaternion');
    x = -x;
    y = -y;
    z = -z;
    w = -w;
  }

  void rotate(double angle, Vector3 axis) {
    double sinAngle = sin(angle);
    double cosAngle = cos(angle);
    double xx = x * x, xy = x * y, xz = x * z, wx = x * w;
    double yy = y * y, yz = y * z, wy = y * w;
    double zz = z * z, wz = w * z;

    x = cosAngle * xx - sinAngle * (xz + wy);
    y = cosAngle * xy + sinAngle * (xx - wy);
    z = cosAngle * xz - sinAngle * (yx + wz);
    w = cosAngle * wx + sinAngle * (yz - xx);
  }

  @override
  String toString() {
    return 'q1 = $x + $y*i + $z*j + $w*k';
  }
}

