import 'dart:async';
import 'dart:convert';
class Quaternion {
  double re = 0.0, im1 = 0.0, im2 = 0.0, im3 = 0.0;

  Quaternion(this.re, this.im1, this.im2, this.im3);

  Quaternion.unit() : this(1.0, 0.0, 0.0, 0.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.random() : this(
    (4 * (Math.random() - 0.5)).toDouble(),
    (4 * (Math.random() - 0.5)).toDouble(),
    (4 * (Math.random() - 0.5)).toDouble(),
    (4 * (Math.random() - 0.5)).toDouble(),
  );

  @override
  bool operator ==(Object other) =>
      re == other.re &&
      im1 == other.im1 &&
      im2 == other.im2 &&
      im3 == other.im3;

  @override
  int get hashCode => re.hashCode ^ im1.hashCode ^ im2.hashCode ^ im3.hashCode;

  Quaternion operator +(Object other) {
    return Quaternion(
      re + other.re,
      im1 + other.im1,
      im2 + other.im2,
      im3 + other.im3,
    );
  }

  Quaternion operator -(Object other) {
    return Quaternion(
      re - other.re,
      im1 - other.im1,
      im2 - other.im2,
      im3 - other.im3,
    );
  }

  Quaternion operator *(Object other) {
    return Quaternion(
      re * other.re - im1 * other.im1 - im2 * other.im2 - im3 * other.im3,
      re * other.im1 + im1 * other.re - im2 * other.im3 - im3 * other.im1,
      re * other.im2 + im2 * other.re - im1 * other.im3 - im3 * other.im2,
      re * other.im3 + im3 * other.re - im1 * other.im2 - im2 * other.im1,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(scalar * re, scalar * im1, scalar * im2, scalar * im3);
  }

  Quaternion conjugate() {
    return Quaternion(re, -im1, -im2, -im3);
  }

  double norm() => (re * re + im1 * im1 + im2 * im2 + im3 * im3).toDouble();

  bool get isUnit => norm() == 1.0;

  bool get isZero => norm() == 0.0;

  bool get isImaginary => re == 0.0 && norm() != 0.0;

  bool get isPureImaginary => re == 0.0 && im1 == 0.0 && im2 == 0.0 && im3 == 0.0;

  double angle() => Math.acos((re * re + im1 * im1 + im2 * im2 + im3 * im3).toDouble() / 4.0);

  Quaternion inverse() {
    if (isZero) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    double d = norm();
    return Quaternion(
      re / d,
      -im1 / d,
      -im2 / d,
      -im3 / d,
    );
  }

  Quaternion normalized() {
    if (isZero) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    double r = norm();
    return Quaternion(re / r, im1 / r, im2 / r, im3 / r);
  }

  void rotate(Quaternion axis, double angle) {
    double sin = Math.sin(angle / 2.0);
    double cos = Math.cos(angle / 2.0);
    double ax = axis.re, ay = axis.im1, az = axis.im2, at = axis.im3;
    re = (re * cos + ax * sin).toDouble();
    im1 = (im1 * cos + ay * sin).toDouble();
    im2 = (im2 * cos + az * sin).toDouble();
    im3 = (im3 * cos + at * sin).toDouble();
  }

  @override
  String toString() {
    String sign = im1 < 0.0 ? '-' : im2 < 0.0 ? '-' : im3 < 0.0 ? '-' : '';
    return 'q1 = $re + $sign $im1 + $sign $im2 + $sign $im3';
  }
}

