class Quaternion {
  double x = 0.0;
  double y = 0.0;
  double z = 0.0;
  double w = 0.0;

  void set(double x, double y, double z, double w) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w;
  }

  void setIdentity() {
    set(0.0, 0.0, 0.0, 1.0);
  }

  void conjugate() {
    this.x = x;
    this.y = -y;
    this.z = -z;
    this.w = w;
  }

  void invert() {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w * -1.0;
  }

  void normalize() {
    double mag = x * x + y * y + z * z + w * w;
    if (mag == 0) {
      setIdentity();
      throw ArgumentError("Cannot normalize zero quaternion");
    }
    this.x = x / mag;
    this.y = y / mag;
    this.z = z / mag;
    this.w = w / mag;
  }

  void add(Quaternion other) {
    this.x = x + other.x;
    this.y = y + other.y;
    this.z = z + other.z;
    this.w = w + other.w;
  }

  void sub(Quaternion other) {
    this.x = x - other.x;
    this.y = y - other.y;
    this.z = z - other.z;
    this.w = w - other.w;
  }

  void multiply(Quaternion other) {
    double t = x * other.w;
    double u = y * other.z;
    double v = z * other.y;
    double w = w * other.x - t * other.z - u * other.y - v * other.x;
    this.x = w;
    this.y = u;
    this.z = v;
    this.w = t;
  }

  void rotate(double angle) {
    double sin = angle * 0.5;
    double cos = 1.0 - sin * sin;
    double tx = x * cos + z * sin;
    double tz = z * cos - x * sin;
    this.x = tx;
    this.z = tz;
    double ty = y * cos - w * sin;
    double wy = w * cos + y * sin;
    this.y = ty;
    this.w = wy;
  }

  void rotateAroundAxis(Quaternion axis, double angle) {
    Quaternion axisNorm = axis.normalize();
    Quaternion rot = Quaternion();
    rot.x = axisNorm.x * axisNorm.x;
    rot.y = axisNorm.y * axisNorm.y;
    rot.z = axisNorm.z * axisNorm.z;
    rot.w = axisNorm.x * axisNorm.y - axisNorm.z * axisNorm.z;
    rotate(angle);
    multiply(rot);
  }

  double length() {
    return (x * x + y * y + z * z + w * w) ^ 0.5;
  }

  Quaternion inverse() {
    if (w == 0) {
      throw ArgumentError("Cannot invert zero quaternion");
    }
    return Quaternion()..set(x, y, z, w * -1.0);
  }

  double dot(Quaternion other) {
    return x * other.x + y * other.y + z * other.z + w * other.w;
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

