    } else if (gap < -6) {
      cycleCount += (gap + 6) ~/ 2;
    }

    uniquePositions += gcd(i - 1, i);
  }

  return {
    'gcd': gcd(uniquePositions, cycleCount),
    'cycleCount': cycleCount,
    'uniquePositions': uniquePositions,
  };
}

