  bool valid = true;

  for (int i = 0; i < tape.length; i++) {
    String ch = tape[i];
    if (ch == '[') {
      stack.add('|');
    } else if (ch == ']') {
      if (stack.isEmpty) {
        valid = false;
        break;
      }
      stack.removeLast();
    } else if (ch == 'P') {
      if (stack.isNotEmpty && stack.last == '|') {
        stack.removeLast();
      }
    } else if (ch == 'D' || ch == 'C') {
      if (stack.isEmpty) {
        valid = false;
        break;
      }
      String last = stack.last;
      if (last == '|' || last == 'D' || last == 'C') {
        valid = false;
        break;
      }
      stack.add(ch);
    } else if (ch == 'S' || ch == 'B' || ch == 'M') {
      if (stack.length < 2 || stack.last != '|') {
        valid = false;
        break;
      }
      String top = stack.removeLast();
      String below = stack.removeLast();
      if (top == 'S') {
        reds.add(below == 'D' ? 1 : below == 'C' ? 2 : 0);
      } else if (top == 'B' && below == 'D') {
        score += 2;
      } else if (top == 'M' && below == 'C') {
        score -= 1;
      } else {
        valid = false;
        break;
      }
    } else if (ch == 'R') {
      if (reds.isEmpty) {
        valid = false;
        break;
      }
      int maxLen = 0;
      int runStart = i;
      for (int j = i + 1; j < tape.length; j++) {
        if (tape[j] == 'R') {
          int len = j - runStart;
          if (len > maxLen) maxLen = len;
        } else if (tape[j] != 'P' && tape[j] != ']') {
          break;
        }
      }
      if (maxLen > 0) {
        score += maxLen * (reds[reds.length - 1] + 1);
      }
    }
  }

  if (!valid || stack.isNotEmpty) {
    return 0.0;
  }

  return (score + (reds.isEmpty ? 0 : reds.fold(0, (a, b) => a + b).toDouble()) / 2.0;
}

