bool fn0(List<int> samples, int referenceValue) {
  Map<int, int> freq = {};
  for (int value in samples) {
    freq[value] = (freq[value] ?? 0) + 1;
  }
  List<int> freqSorted = List<int>.from(freq.entries);
  freqSorted.sort((a, b) => a.key.compareTo(b.key));
  int targetStart = 0;
  int targetEnd = freqSorted.length;
  for (int i = 0; i < freqSorted.length; i++) {
    if (freqSorted[i].key > referenceValue) {
      targetStart = i;
      break;
    }
  }
  int lo = 0;
  int hi = freqSorted.length - targetStart;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (freqSorted[targetStart + mid].key <= referenceValue) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  if (lo == 0) {
    return false;
  }
  return freqSorted[targetStart + lo].key == referenceValue;
}

