Map<String, int> fn0(List<int> seeds, int targetSeed) {
  if (seeds.isEmpty) return {};
  int n = seeds.length;
  if (targetSeed >= n) return {};

  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(n + 1, 0),
  );

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      dp[i][j] = dp[i - 1][j] + dp[i][j - 1] + seeds[i - 1] * seeds[j - 1];
    }
  }

  Map<String, int> result = {};
  for (int j = 1; j <= n; j++) {
    int currentSum = dp[n][j];
    int diff = currentSum - targetSeed;
    if (diff == 0) {
      result["$targetSeed-$j"] = 1;
      break;
    }
    int left = 0;
    int right = n;

    while (left < right) {
      int mid = left + (right - left) ~/ 2;
      if (dp[mid][j] <= diff) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    int firstLessThan = left;
    int lastLessThan = n - firstLessThan;

    result["$targetSeed-$firstLessThan..$targetSeed-$lastLessThan"] =
        (result["$targetSeed-$firstLessThan..$targetSeed-$lastLessThan"] ?? 0) + 1;
  }

  return result;
}

