void fn0() {

  const int value = 0x12345678;

  String byteOrder(int v) {
    if ((v & 0x01) == 0) {
      return 'little-endian';
    }
    return 'big-endian';
  }

  String bytesToHex(List<int> bytes) {
    List<String> parts = bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).toList();
    return parts.join(' ');
  }

  int fromLittleEndian(List<int> bytes) {
    int result = 0;
    for (int i = 0; i < bytes.length; i++) {
      result |= (bytes[i] << (i * 8));
    }
    return result;
  }

  int fromBigEndian(List<int> bytes) {
    int result = 0;
    for (int i = bytes.length - 1; i >= 0; i--) {
      result |= (bytes[i] << (i * 8));
    }
    return result;
  }

  String bytesToHexFor(List<int> bytes, String prefix) {
    String formatted = bytesToHex(bytes);
    String description = byteOrder(bytes[0]);
    return '$prefix: $formatted, $description';
  }

  print('Value from little-endian bytes: 0x${fromLittleEndian(List.filled(4, value & 0xFF)).toRadixString(16)}');
  print('Value from big-endian bytes: 0x${fromBigEndian(List.filled(4, value & 0xFF)).toRadixString(16)}');

  print('Little-endian bytes: ${List.filled(4, value & 0xFF)}');
  print('Big-endian bytes: ${List.filled(4, value & 0xFF).reversed.toList()}');

  print('Host system is ${byteOrder(value)}');

  List<int> bytesLittle = List.filled(4, value & 0xFF);
  print('Little-endian: ${bytesToHexFor(bytesLittle, 'Little')}\n');

  List<int> bytesBig = List.filled(4, value & 0xFF).reversed.toList();
  print('Big-endian: ${bytesToHexFor(bytesBig, 'Big')}\n');

  List<int> swapped = List.filled(4, value & 0xFF).reversed.toList();
  print('Swapped from little to big: ${bytesToHexFor(swapped, 'Swapped')}\n');
}

