      String resourceAction = '$resource-$action';
      auditLog[resourceAction] = (auditLog[resourceAction] ??<String, String>[])..add(role);
      print('  ➜ Access GRANTED (Role: $role)');
    } else {
      print('  ➜ Access DENIED (Insufficient permissions)');
    }
