        (currentRole ?? 'viewer') == 'moderator' &&
        resourceAccess[resource]!.contains(action);
  }

  void printResourceAccessMatrix(Map<String, List<String>> accessMatrix) {
    String header = '  ';
    for (String resource in accessMatrix.keys) {
      header += resource.padRight(10);
    }
    print(header);

    for (String resource in accessMatrix.keys) {
      String line = '$resource: ';
      for (String action in accessMatrix[resource]!) {
        line += action.padRight(10);
      }
      print(line);
    }
