    String latestTime = '';

    auditLog.forEach((resource, actions) {
      for (String action in actions) {
        if (action != recentAction) {
          recentAction = action;
          latestTime = actions.last;
        }
      }
    });

    print('Recent Access Attempts:');
    print('  $recentAction at ${latestTime}');
