void fn0() {

  String byteStreamString(List<int> bytes) {
    return bytes
        .map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase())
        .join(' ');
  }

  List<int> byteArray(String stream) {
    List<int> result = [];
    for (int i = 0; i < stream.length; i += 2) {
      int byte = int.parse(stream.substring(i, i + 2), radix: 16);
      result.add(byte);
    }
    return result;
  }

  List<int> toBytes(double value) {
    int* intPointer = &value;
    List<int> bytes = [];
    for (int i = 0; i < 8; i++) {
      bytes.add(intPointer[i]);
    }
    return bytes;
  }

  double fromBytes(List<int> bytes) {
    int* intPointer = &bytes[0];
    double result = 0.0;
    for (int i = 0; i < 8; i++) {
      result += intPointer[i] / (1 << i);
    }
    return result;
  }

  List<int> littleEndian(List<int> bigEndian) {
    List<int> result = [];
    for (int i = 0; i < bigEndian.length; i++) {
      result.add(bigEndian[i]);
    }
    return result;
  }

  List<int> bigEndian(List<int> littleEndian) {
    List<int> result = [];
    for (int i = littleEndian.length - 1; i >= 0; i--) {
      result.add(littleEndian[i]);
    }
    return result;
  }

  int swap16(int value) {
    return ((value >> 8) & 0xFF) | (value << 8);
  }

  int swap32(int value) {
    return ((value >> 24) & 0xFF) |
        ((value >> 8) & 0xFF) << 8 |
        ((value << 8) & 0xFF) << 16 |
        ((value << 24) & 0xFF);
  }

  void showEndianness(String description, Object value) {
    print('$description: $value');
    if (value is int) {
      print('Binary: ${(value & 0xFF).toRadixString(16).padLeft(2, '0').toUpperCase()}');
    } else if (value is List<int>) {
      print('Original 16-bit values: ${value.map((v) => v.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');
      print('Swapped values: ${value.map((v) => v.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');
    } else if (value is double) {
      print('Float value: ${value.toStringAsFixed(2)}');
    } else if (value is List<int>) {
      print('As Little Endian bytes: ${value.map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');
      print('As Big Endian bytes: ${bigEndian(value).map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');
      print('Reconstructed: [${fromBytes(value)}]');
    }
  }

  int data = 0x12345678;

  print('System Information:');
  print('System is Little Endian');
  print('Host port: 8080');

  showEndianness('Network Byte Order Example:', data);

  List<int> network = [0x78, 0x56, 0x34, 0x12];
  print('Network bytes: [${network.map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}]');

  int hostValue = fromBytes(network);
