  print('To bytes: [${bytes.map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}]');
  double reconstructed = fromBytes(bytes);
  print('Back to host: $reconstructed');

  int swap16Value = swap16(data);
  print('16-bit swap of 0x${data.toRadixString(16).toUpperCase().padLeft(4, '0')} → 0x${swap16Value.toRadixString(16).toUpperCase().padLeft(4, '0')}');

  int swap32Value = swap32(data);
  print('32-bit swap of 0x${data.toRadixString(16).toUpperCase().padLeft(4, '0')} → 0x${swap32Value.toRadixString(16).toUpperCase().padLeft(4, '0')}');

  List<int> byteArrayBE = [0x0D, 0x09, 0x19, 0x2D];
  List<int> byteArrayLE = [0x2D, 0x19, 0x09, 0x0D];
