  print('Byte stream (LE): ${byteStreamString(byteArrayLE)}');

  List<int> bigEndianValue = [0x0D, 0x09, 0x19, 0x2D];
  List<int> littleEndianValue = [0x2D, 0x19, 0x09, 0x0D];
  showEndianness('Array Endianness Conversion:', bigEndianValue);
  showEndianness('Array Endianness Conversion:', littleEndianValue);

  List<int> both = [0x0D, 0x09, 0x19, 0x2D, 0x43, 0x4B, 0x57, 0x65];
  print('Endianness Swapping:');
