import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<String>> transactions = [
    ['Milk', 'Bread', 'Butter'],
    ['Milk', 'Bread'],
    ['Bread'],
    ['Milk'],
    ['Bread', 'Butter'],
    ['Milk', 'Butter'],
  ];

  double minSupport = 0.5;
  double minConfidence = 0.7;

  Set<String> items = {};
  for (var trans in transactions) {
    for (var item in trans) {
      if (!items.contains(item)) {
        items.add(item);
      }
    }
  }

  Map<String, int> freq = {};
  for (var trans in transactions) {
    Map<String, int> count = {};
    for (var item in trans) {
      count[item] = (count[item] ?? 0) + 1;
    }
    Set<String> frequent = count.entries.where((e) => e.value >= minSupport).map((e) => e.key).toList();
    for (var item in frequent) {
      freq[item] = (freq[item] ?? 0) + 1;
    }
  }

  Set<String> candidateSet = {};
  String? lastItem;

  bool isFrequent(String item) {
    return freq[item]! >= minSupport;
  }

  bool isFrequent(List<String> items) {
    return items.every((e) => isFrequent(e));
  }

  do {
    Set<String> frequent = {};
    for (var item in items) {
      if (isFrequent(item)) {
        frequent.add(item);
      }
    }
    if (frequent.isEmpty) {
      break;
    }

    Set<String> candidateSet = {};
    for (var item in frequent) {
      for (var newItem in ['Milk', 'Bread', 'Butter']) {
        if (item != newItem && isFrequent(item + newItem)) {
          candidateSet.add(item + newItem);
        }
      }
    }

    if (candidateSet.isEmpty) {
      break;
    }

    Map<String, int> counts = {};
    for (var trans in transactions) {
      for (var item in candidateSet) {
        if (trans.contains(item)) {
          counts[item] = (counts[item] ?? 0) + 1;
        }
      }
    }

    List<String> candidates = candidateSet.toList();
    candidates.sort();

    Map<String, Set<String>> frequentItemsets = {};
    Map<String, int> minSupportCount = {};

    for (var item in candidates) {
      int support = 0;
      for (var trans in transactions) {
        if (trans.contains(item)) {
          support++;
        }
      }
      if (support >= minSupport) {
        frequentItemsets[item] = {};
        minSupportCount[item] = support;
      }
    }

    Set<String> frequent = frequentItemsets.entries.where((e) => e.value.length >= 2 && e.value.length == 2 && e.value.length == 3 && e.value.length == 4 && e.value.length == 5).map((e) => e.key).toList();
    for (var item in frequent) {
      freq[item] = (freq[item] ?? 0) + 1;
    }

    if (lastItem != null && !frequent.contains(lastItem + item)) {
      candidateSet.remove(lastItem + item);
    }

    lastItem = item;
  } while (candidateSet.isNotEmpty);

  print('Frequent Itemsets:');
  print(frequentItemsets);

  Map<String, List<String>> associationRules = {};

  for (var item in frequent) {
    if (freq[item]! >= minSupport) {
      List<String> supportItems = [];
      for (var trans in transactions) {
        if (trans.contains(item)) {
          supportItems.add(trans.remove(item));
        }
      }
      supportItems.sort();

      for (var supportItem in supportItems) {
        String rule = '${item} -> $supportItem';
        double confidence = minSupportCount[item]! / freq[supportItem]!;
        if (confidence >= minConfidence) {
          associationRules[rule] = (associationRules[rule] ?? 0) + 1;
        }
      }
    }
  }

  List<String> rules = associationRules.entries.where((e) => e.value > 1).map((e) => e.key).toList();
  rules.sort();

  print('\nAssociation Rules:');
  for (var rule in rules) {
    print('${rule} (support: ${minSupportCount[rule.split(' -> ')[0]} / ${freq[rule.split(' -> ')[0]} = ${minSupportCount[rule.split(' -> ')[0]} / ${freq[rule.split(' -> ')[1]} = ${minConfidence}, confidence: ${minConfidence})');
  }
}

