    [‘Milk’, ‘Bread’],
    [‘Milk’],
    [‘Bread’, ‘Butter’],
    [‘Bread’],
    [‘Milk’, ‘Bread’, ‘Butter’, ‘Milk’],
    [‘Milk’, ‘Bread’, ‘Butter’, ‘Bread’],
    [‘Bread’, ‘Butter’],
  };

  const double minSupport = 0.5;
  const double minConfidence = 0.7;

  int k = 1;

  final Map<List<String>, int> itemCounts = {};
  final Map<List<String>, Set<List<String>>> frequentItemsets = {};

  for (final transaction in transactions) {
    if (transaction.isEmpty) continue;
    if (transaction.length > k) continue;

    for (int i = 0; i < (1 << transaction.length); i++) {
      final Set<String> itemset = {};
      for (int j = 0; j < transaction.length; j++) {
        if ((i & (1 << j)) != 0) {
          itemset.add(transaction[j]);
        }
      }

      final int support = itemset.length / transactions.length;
      if (support >= minSupport) {
        itemCounts[itemset] = (itemCounts[itemset] ?? 0) + 1;
        frequentItemsets.putIfAbsent(itemset, () => <List<String>>{}).add(transaction);
      }
    }
  }

  final Set<List<String>> frequentItemsetTransactions = {};
  for (final itemset in frequentItemsets.keys) {
    if (frequentItemsets[itemset]!.length == k) {
      final support = itemCounts[itemset]!;
      frequentItemsetTransactions.addAll(frequentItemsets[itemset]!);
    }
  }

  Map<List<String>, Set<List<String>>> frequentRuleSets = {};
  for (final transaction in frequentItemsetTransactions) {
    if (transaction.length <= k) {
      final itemset = transaction.toList();
      if (itemset.length == k) {
        final itemsetSupport = itemCounts[itemset]!;
        final Set<String> frequentConsequents = {};
        for (final transaction in frequentItemsetTransactions) {
          if (!transaction.containsAll(itemset)) {
            frequentConsequents.add(transaction.toList()..remove(itemset.first));
          }
        }

        final Set<List<String>> itemsetSubsets = {itemset};
        final List<List<String>> expanded = [];

        while (itemsetSubsets.isNotEmpty) {
          final List<String> itemset = itemsetSubsets.removeAt(0);
          final int itemsetSupport = itemCounts[itemset]!;
          if (itemsetSupport >= minSupport) {
            for (final List<String> consequent in frequentConsequents) {
              if (itemset.length == k) {
                final support = itemsetSupport / frequentItemsetTransactions.length;
                if (support >= minConfidence) {
                  expanded.add(itemset + consequent);
                }
              }
            }
          }
        }

        frequentRuleSets[itemset] = expanded;
      }
    }
  }

  final List<String> rules = [];
  for (final itemset in frequentItemsetTransactions) {
    final Set<String> frequentConsequents = {};
    for (final transaction in frequentItemsetTransactions) {
      if (!transaction.containsAll(itemset)) {
        frequentConsequents.add(transaction.toList()..remove(itemset.first));
      }
    }

    final Set<List<String>> itemsetSubsets = {itemset};
    final List<List<String>> expanded = [];

    while (itemsetSubsets.isNotEmpty) {
      final List<String> itemset = itemsetSubsets.removeAt(0);
      final int itemsetSupport = itemCounts[itemset]!;
      if (itemsetSupport >= minSupport) {
        for (final List<String> consequent in frequentConsequents) {
          if (itemset.length == k) {
            final support = itemsetSupport / frequentItemsetTransactions.length;
            if (support >= minConfidence) {
              expanded.add(itemset + consequent);
            }
          }
        }
      }
    }

    for (final List<String> rule in expanded) {
      final String supportStr = itemsetSupport.toString() + ' (' + minSupport.toString() + ')';
      final String confidenceStr = minConfidence.toString() + ' (' + minConfidence.toString() + ')';
      rules.add(rule.join(' -> ') + ' (support: $supportStr, confidence: $confidenceStr)');
    }
  }

  rules.sort();

  print('Frequent Itemsets:');
  print(frequentItemsetTransactions.join(', '));
  print('\nAssociation Rules:');
  for (final rule in rules) {
    print(rule);
  }
}

