  Map<int, Map<int, int>> frequentItemsets = {};

  for (int item = 0; item < k - 1; item++) {
    Map<int, int> currentFreq = {};

    for (int itemSet = 0; itemSet < frequentItemsList.length; itemSet++) {
      if (frequentItemsList.contains(itemSet)) {
        if (currentFreq.containsKey(itemSet)) {
          currentFreq[itemSet] = currentFreq[itemSet]! + 1;
        } else {
          currentFreq[itemSet] = 1;
        }
      }
    }

    frequentItemsets[k - 1] = currentFreq;
  }

  List<int> candidateSet = [];
  Set<int> closed = {};

  for (int item = 0; item < k - 1; item++) {
    List<int> items = frequentItemsets[k - 1]!.keys.toList();
    items.sort();

    if (items.length == k - 1) {
      bool allSubsetsFrequent = true;

      for (int mask = 0; mask < (1 << k) - 1; mask++) {
        Set<int> subset = {};

        for (int j = 0; j < k - 1; j++) {
          if ((mask & (1 << j)) != 0) {
            subset.add(items[j]);
          }
        }

        if (!itemFreq.containsKey(subset)) {
          allSubsetsFrequent = false;
          break;
        }
      }

      if (allSubsetsFrequent) {
        candidateSet.add(items);
        closed.add(items);
      }
    }
  }

  Map<int, Set<int>> frequentItemsetsWithSupport = {};
  Map<int, Set<int>> frequentItemsetsWithConfidence = {};

  while (candidateSet.isNotEmpty) {
    List<int> current = candidateSet.removeAt(0);

    Map<int, int> support = {};

    for (int itemSet = 0; itemSet < frequentItemsList.length; itemSet++) {
      if (frequentItemsList.contains(itemSet)) {
        if (current.contains(itemSet)) {
          support[itemSet] = (support[itemSet] ?? 0) + 1;
        }
      }
    }

    if (support.length == current.length) {
      frequentItemsetsWithSupport[current] = support;
    }

    Map<int, int> confidence = {};
    int totalSupport = 0;

    for (int itemSet = 0; itemSet < frequentItemsList.length; itemSet++) {
      if (frequentItemsList.contains(itemSet)) {
        if (current.contains(itemSet)) {
          confidence[itemSet] = (support[itemSet] ?? 0) / frequentItems;
        }
      }

      if (support.length == current.length) {
        totalSupport += support[itemSet]!;
      }
    }

    if (totalSupport > 0 && confidence.length == current.length) {
      frequentItemsetsWithConfidence[current] = confidence;

      for (var entry in confidence.entries) {
        if (entry.value >= minConfidence) {

          String itemLabels = current.map((s) => s.toString()).join(' ');
          print('$itemLabels (support: ${entry.value * 100}%, confidence: ${entry.value * 100}%)');
        }
      }
    }
  }

  print('\nAssociation Rules:');
  print('=================');

  for (var entry in frequentItemsetsWithConfidence.entries) {
    List<int> itemset = entry.key;
    Map<int, int> confidence = entry.value;

    int minSupport = minSupport * k; 

    if (confidence.isNotEmpty && confidence.values.first * minSupport > minSupport * minConfidence) {

      String itemLabels = itemset.map((s) => s.toString()).join(' ');
      print('$itemLabels -> ${itemset.removeLast().toString()} (support: ${confidence.values.first * 100}%, confidence: ${confidence.values.first * 100}%)');
    }
  }
}

