    if (bucketCounts[i] < 0) return false;
    buckets.add([i, bucketCounts[i]]);
  }
  buckets.sort((a, b) {
    if (a[1] != b[1]) return a[1].compareTo(b[1]);
    return a[0].compareTo(b[0]);
  });
  List<int> cum = [0];
