    if (diff == 0) {
      row.add(0);
    } else if (diff.abs() == 1) {
      row.add(diff.isNegative ? -1 : 1);
    } else {
      var gap = (diff - 2) ~/ 3;
      row.add(gap.isEven ? 0 : -gap);
    }
    rows.add(row);
  }
  var scores = <int>[];
  for (var row in rows) {
    var score = 0;
    for (var cell in row) {
      if (cell == 0) {
        score += 2;
      } else if (cell == -1) {
        score -= 1;
      } else if (cell == 1) {
        score += 1;
      } else {
        score += cell.abs();
      }
    }
    scores.add(score);
  }
  return scores;
}

