bool fn0(List<List<int>> grid, int maxJump) {
  if (grid.isEmpty || grid[0].isEmpty) {
    return false;
  }

  int rows = grid.length;
  int cols = grid[0].length;

  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (grid[i][j] == 0) {
        continue;
      }

      int minVal = grid[i][j];
      for (int d = -maxJump; d <= maxJump; d++) {
        int ni = i + d;
        int nj = j + d;

        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
          if (grid[ni][nj] < minVal) {
            minVal = grid[ni][nj];
          }
        }
      }

      dp[i][j] = minVal;
    }
  }

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (dp[i][j] == 0) {
        continue;
      }

      bool found = false;
      for (int d = -maxJump; d <= maxJump; d++) {
        int ni = i + d;
        int nj = j + d;

        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
          if (grid[ni][nj] == dp[i][j]) {
            found = true;
            break;
          }
        }
      }

      if (!found) {
        return false;
      }
    }
  }

  List<List<int>> flattened = [];
  for (int i = 0; i < rows * cols; i++) {
    int row = i ~/ cols;
    int col = i % cols;
    if (grid[row][col] == 0) {
      continue;
    }

    List<int> path = [row, col];
    for (int d = -maxJump; d <= maxJump; d++) {
      int ni = row + d;
      int nj = col + d;

      if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
        path.add(grid[ni][nj]);
      }
    }

    flattened.add(path);
  }

  List<List<int>> uniquePaths = [];
  int len = 1;
  for (int i = 0; i < flattened.length; i++) {
    if (i > 0 && flattened[i] != flattened[i - 1]) {
      uniquePaths.add(List.from(flattened.sublist(i - 1, i)));
      len++;
    }
  }

  for (int i = 1; i < uniquePaths.length; i++) {
    int dx = (uniquePaths[i][0] - uniquePaths[i - 1][0]).abs();
    int dy = (uniquePaths[i][1] - uniquePaths[i - 1][1]).abs();

    if (dx + dy > maxJump) {
      return false;
    }
  }

  return true;
}

