List<int> fn0(List<List<int>> rounds, int streak) {
  if (streak <= 0) return [];
  final counts = [0, 0, 0, 0, 0];
  var current = [0, 0, 0, 0, 0];
  var best = [0, 0, 0, 0, 0];
  var bestSoFar = 0;
  for (final round in rounds) {
    var newCurrent = List<int>.from(current);
    for (final die in round) {
      for (int i = 0; i < 5; i++) {
        newCurrent[i] += die == i + 1 ? streak : -streak;
      }
      if (newCurrent[i] > best[i]) best[i] = newCurrent[i];
    }
    var bestCount = 0;
    for (int v in best) if (v > 0) bestCount++;
    if (bestCount > bestSoFar) {
      bestSoFar = bestCount;
      current = best;
    } else if (bestCount == 0) {
      current = [0, 0, 0, 0, 0];
    } else {
      for (int i = 0; i < 5; i++) {
        if (current[i] > 0 && (newCurrent[i] < 0 || newCurrent[i] > current[i])) {
          current[i] = newCurrent[i];
        }
      }
    }
    counts[current[0] - 1]++;
  }
  return counts;
}

