List<int> fn0(List<List<int>> intervals) {
  if (intervals.isEmpty) return [];
  List<int> xs = [];
  List<int> ys = [];
  for (var iv in intervals) {
    xs.add(iv[0]);
    xs.add(iv[2]);
    ys.add(iv[1]);
    ys.add(iv[3]);
  }
  List<List<int>> areas = [];
  for (int i = 0; i < xs.length - 1; i++) {
    int x1 = xs[i], y1 = ys[i], x2 = xs[i + 1], y2 = ys[i + 1];
    areas.add([x1, y1, x2, y2]);
  }
  List<int> overlapAreas = [];
  List<int> unionAreas = [];
  int n = areas.length;
  for (int i = 0; i < (1 << n) - 1; i++) {
    List<int> a = [], b = [];
    for (int j = 0; j < n; j++) {
      if ((i & (1 << j)) != 0) {
        a.add(areas[j]);
      } else {
        b.add(areas[j]);
      }
    }
    int overlap = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]);
    int union = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]);
    overlapAreas.add(overlap);
    unionAreas.add(union);
  }
  int total = 0;
  for (int i = 0; i < n - 1; i++) {
    if (i % 2 == 0) {
      total += overlapAreas[i];
    }
  }
  List<int> result = [total, unionAreas[0]];
  for (int i = 1; i < n - 1; i++) {
    int j = i - 1, k = i + 1;
    int overlapPrev = (i % 2 == 0) ? overlapAreas[j] : unionAreas[j];
    int overlapNext = (i % 2 == 0) ? overlapAreas[k] : unionAreas[k];
    result.add(overlapPrev > overlapNext ? overlapPrev - overlapNext : unionAreas[j] + unionAreas[k]);
  }
  return result;
}

