class Point {
  final double x, y;

  Point(this.x, this.y);

  double distanceFromOrigin() => sqrt(x * x + y * y);
}

class Rectangle {
  final double x, y;
  final double width, height;

  Rectangle(this.x, this.y, this.width, this.height);

  Rectangle extendX(double x) =>
      Rectangle(x, y, width, height);

  Rectangle extendY(double y) =>
      Rectangle(x, y, width, height);

  Rectangle shrink(double factor) =>
      Rectangle(x + factor * x, y + factor * y, width * factor, height * factor);
}

