  const Point.unitLeft() : this(-1, 1);

  const Point.unitRight() : this(1, -1);

  const Point.unitUp() : this(1, 0);

  const Point.unitDown() : this(0, -1);

  const Point.random() : this(rand.nextDouble() * 100 - 50, rand.nextDouble() * 100 - 50);

  const Point.within(double minX, double maxX, double minY, double maxY) : this(rand.nextDouble() * (maxX - minX) + minX, rand.nextDouble() * (maxY - minY) + minY);

  const Point.unitCircle() : this(
    sqrt(2) * rand.nextDouble() - sqrt(2),
    sqrt(2) * rand.nextDouble() - sqrt(2),
  );

  @override
  bool operator ==(Object other) =>
      other is Point && x == other.x && y == other.y;

  @override
  int get hashCode => x.hashCode ^ y.hashCode;

  const Point.center(double centerX, double centerY, double radius) : this(centerX - radius, centerY - radius);

  const Point.circle(double centerX, double centerY, double radius) : this(centerX + radius, centerY + radius);

  const Point.ellipse(
    double centerX,
    double centerY,
    double semiMajor,
    double semiMinor,
  ) : this(
        centerX + semiMajor * rand.nextDouble() - semiMajor / 2,
        centerY + semiMinor * rand.nextDouble() - semiMinor / 2,
      );
}

