class Point {
  final double x;
  final double y;

  const Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';

  bool operator <(const Point other) =>
      List.filled(2, other.$x).reduce((a, b) => a + b) <
      List.filled(2, this.x).reduce((a, b) => a + b);

  bool operator <=(const Point other) =>
      List.filled(2, other.$x).reduce((a, b) => a + b) <=
      List.filled(2, this.x).reduce((a, b) => a + b);

  bool operator >(const Point other) =>
      List.filled(2, other.$x).reduce((a, b) => a + b) >
      List.filled(2, this.x).reduce((a, b) => a + b);

  bool operator >=(const Point other) =>
      List.filled(2, other.$x).reduce((a, b) => a + b) >=
      List.filled(2, this.x).reduce((a, b) => a + b);
}

