  double distance(int i, int j) {
    double sum = 0;
    for (int d = 0; d < points[i].length; d++) {
      sum += pow(points[i][d] - points[j][d], 2);
    }
    return sum;
  }

  double centroidDistance(List<double> c) {
    double distance = 0;
    for (int d = 0; d < c.length; d++) {
      distance += pow(c[d] - points[d].toDouble(), 2);
    }
    return distance;
  }

  List<List<double>> centroids = List.generate(k, (_) => List.filled(points[0].length, 0.0));

