  double eps = 1.0;
  int maxIterations = 100;
  int iteration = 0;

  while (iteration < maxIterations) {

    int minDistance = double.infinity;
    int closest = -1;

    for (int i = 0; i < k; i++) {
      double dist = centroidDistance(centroids[i]);
      if (dist < minDistance) {
        minDistance = dist;
        closest = i;
      }
    }

    if (minDistance == double.infinity) {
      break; 
    }

    List<int> newClusterAssignment = List.filled(n, -1);

    for (int j = 0; j < n; j++) {
      double minDist = double.infinity;
      int best = closest;

      for (int c = 0; c < k; c++) {
        if (c != closest) {
          double d = distance(j, centroids[c]);
          if (d < minDist) {
            minDist = d;
            best = c;
          }
        }
      }

      newClusterAssignment[j] = best;
    }

    bool changed = false;

    for (int i = 0; i < k; i++) {
      if (centroids[i].isNotEmpty &&
          newClusterAssignment.every((j) => clusterAssignment[j] == i)) {
