          if (clusterAssignment[j] == i) {
            points[j] = centroids[i];
          }
        }

        centroids[i] = List.from(points[i]);
      }
    }

    if (!changed) {
      break;
    }

    clusterAssignment = newClusterAssignment;
    iteration++;
  }

  print('Converged in $iteration iteration(s).');

  for (int i = 0; i < k; i++) {
    print('Cluster $i:');
    print('  centroid: ${centroids[i]}');
