            case 1:
              return 'G';
            case 255:
              return 'R';
            default:
              return '';
          }
      ];
      uniqueNames.add('${rgb[0]},${rgb[1]},${rgb[2]}');
      uniqueNames.add(pixels.join('->'));
    }
  }
  final List<String> sorted = uniqueNames.toList()
    ..sort((a, b) {
      final List<String> pa = a.split('->');
      final List<String> pb = b.split('->');
      final List<int> ra = [
        int.parse(pa[0]),
        int.parse(pa[1]),
