      final String mb = maxColors[1];
      final int ra0 = ra[0];
      final int ra1 = ra[1];
      final int ra2 = ra[2];
      final int rb0 = rb[0];
      final int rb1 = rb[1];
      final int rb2 = rb[2];
      final int swap = (ma == 'B' && mb == 'G')
          ? ra0 - rb0
          : (ma == 'G' && mb == 'R')
              ? ra1 - rb1
              : ra2 - rb2;
      if (swap != 0) {
        return swap;
      }
      return a.compareTo(b);
    });
